#ifndef ADMIN_H
#define ADMIN_H

static const char adminPage[] = R"admin(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Rounder Control</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-sRIl4kxILFvY47J16cr9ZwB07vP4J8+LH7qKQnuqkuIAvNWLzeN8tE5YBujZqJLB" crossorigin="anonymous"><style>bodybody{font-size:1.5rem} .form-control,.btn{font-size:1.5rem}</style></head><body><div class="container py-5"><div class="row justify-content-center"><div class="col-12 col-md-10 col-lg-8"><div class="text-center mb-4"><h1 class="h2">Rounter Control Panel</h1><p class="text-muted">View and manage the displayed round and timer for the session.</p><div class="d-flex justify-content-center mb-3"><button id="refreshBtn" class="btn btn-sm btn-outline-secondary">Refresh</button></div></div><div class="card mb-4 shadow-sm"><div class="card-body"><div class="row g-3"><div class="col-12"><div class="row g-2 align-items-center"><div class="col-auto"><label for="roundInput" class="col-form-label">Round</label></div><div class="col"><input type="number" pattern="[0-9]*" inputmode="numeric" class="form-control form-control-sm" id="roundInput" placeholder="$$counter$$"></div><div class="col-auto d-flex gap-2"><button id="setRoundBtn" type="button" class="btn btn-primary btn-sm">Set</button><button id="plusBtn" type="button" class="btn btn-outline-secondary btn-sm">+</button><button id="minusBtn" type="button" class="btn btn-outline-secondary btn-sm">−</button></div></div></div><div class="col-12"><div class="row g-2 align-items-center"><div class="col-auto"><label for="timerInput" class="col-form-label">Timer</label></div><div class="col"><input type="number" pattern="[0-9]*" inputmode="numeric" class="form-control form-control-sm" id="timerInput" placeholder="$$timer$$"></div><div class="col-auto d-flex gap-2"><button id="setTimerBtn" type="button" class="btn btn-primary btn-sm">Set</button><button id="saveTimerBtn" type="button" class="btn btn-secondary btn-sm">Save</button><button id="startTimerBtn" type="button" class="btn btn-success btn-sm">Start</button></div></div></div><div class="col-12"><div class="d-grid"><button id="resetBtn" type="button" class="btn btn-danger btn-sm">Reset</button></div></div></div></div></div><div class="card mb-4 shadow-sm"><div class="card-header d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">WiFi Credentials</h2><button id="toggleWifiBtn" class="btn btn-sm btn-outline-secondary" type="button" data-bs-toggle="collapse" data-bs-target="#wifiPanel" aria-expanded="false" aria-controls="wifiPanel">Show</button></div><div class="collapse" id="wifiPanel"><div class="card-body"><div class="row g-3"><div class="col-12"><div class="row g-2 align-items-center"><div class="col-auto"><label for="ssidInput" class="col-form-label">SSID</label></div><div class="col"><input type="text" class="form-control form-control-sm" id="ssidInput" placeholder="SSID"></div></div></div><div class="col-12"><div class="row g-2 align-items-center"><div class="col-auto"><label for="pwdInput" class="col-form-label">Password</label></div><div class="col"><input type="password" class="form-control form-control-sm" id="pwdInput" placeholder="Password"></div></div></div><div class="col-12"><div class="d-grid"><button id="setWifiBtn" type="button" class="btn btn-primary btn-sm">Store & Connect</button></div></div></div></div></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js" integrity="sha384-FKyoEForCGlyvwx9Hj09JcYn3nv7wiPVlz7YYwJrWVcXK/BmnVDxM+D2scQbITxI" crossorigin="anonymous"></script><script>const post=(url,msg,rld)=>fetch(url,{method:'POST'}).then(r=>{if(!r.ok)throw 0;return r.text()}).then(()=>rld&&location.reload()).catch(()=>alert(msg));const del=(url,msg)=>fetch(url,{method:'DELETE'}).then(r=>{if(!r.ok)throw 0;return r.text()}).then(()=>location.reload()).catch(()=>alert(msg));document.getElementById('setRoundBtn').onclick=()=>{const v=document.getElementById('roundInput').value.trim();v?post(`/counter?val=${encodeURIComponent(v)}`,'Failed to set round.',true):alert('Enter round value.')};document.getElementById('plusBtn').onclick=()=>post('/plus','Failed to increment.',true);document.getElementById('minusBtn').onclick=()=>post('/minus','Failed to decrement.',true);document.getElementById('setTimerBtn').onclick=()=>{const v=document.getElementById('timerInput').value.trim();v?post(`/timer?val=${encodeURIComponent(v)}`,'Failed to set timer.',true):alert('Enter timer value.')};document.getElementById('saveTimerBtn').onclick=()=>{const v=document.getElementById('timerInput').value.trim();v?post(`/timer?val=${encodeURIComponent(v)}&save=true`,'Failed to save timer.',true):alert('Enter timer value.')};document.getElementById('startTimerBtn').onclick=()=>{post(`/timer`,'Failed to start timer.',true)};document.getElementById('setWifiBtn').onclick=()=>{const s=document.getElementById('ssidInput').value.trim();if(!s){alert('Enter SSID.');return;}const p=document.getElementById('pwdInput').value.trim();post(`/wifi?ssid=${encodeURIComponent(s)}&pwd=${encodeURIComponent(p)}`,'Failed to set WiFi.',false)};document.getElementById('resetBtn').onclick=()=>confirm('Reset?')&&del('/reset','Failed to reset.');const fetchInfo=()=>fetch('/info').then(r=>r.ok?r.json():null).then((info)=>{if(!info)throw 0;if(info.counter!==undefined)document.getElementById('roundInput').placeholder=info.counter;if(info.timer!==undefined)document.getElementById('timerInput').placeholder=info.timer}).catch(()=>alert('Failed to fetch info.'));const wifiPanel=document.getElementById('wifiPanel');const toggleWifiBtn=document.getElementById('toggleWifiBtn');if(wifiPanel&&toggleWifiBtn){wifiPanel.addEventListener('shown.bs.collapse',()=>toggleWifiBtn.textContent='Hide');wifiPanel.addEventListener('hidden.bs.collapse',()=>toggleWifiBtn.textContent='Show')}document.getElementById('refreshBtn').onclick=fetchInfo;fetchInfo();</script></body></html>)admin";

#endif
